"""Cliff walking (SARSA vs Q-learning) and maximisation bias (Q-learning vs Double Q-learning)."""
import numpy as np
rng = np.random.default_rng(1)
R, C = 4, 12; START, GOAL = (3, 0), (3, 11)
MOVES = [(-1, 0), (0, 1), (1, 0), (0, -1)]
def step(s, a):
    r, c = s[0] + MOVES[a][0], s[1] + MOVES[a][1]
    r, c = min(max(r, 0), R - 1), min(max(c, 0), C - 1)
    if r == 3 and 1 <= c <= 10: return START, -100          # fell off the cliff
    return (r, c), -1
def eps_greedy(Q, s, eps=0.1):
    return int(rng.integers(4)) if rng.random() < eps else int(np.argmax(Q[s] + rng.random(4) * 1e-9))

def learn(kind, episodes=500, alpha=0.5):
    Q = np.zeros((R, C, 4)); totals = []
    for _ in range(episodes):
        s, tot = START, 0; a = eps_greedy(Q, s)
        while s != GOAL:
            s2, r = step(s, a); tot += r; a2 = eps_greedy(Q, s2)
            target = r + (0 if s2 == GOAL else (Q[s2][a2] if kind == "sarsa" else Q[s2].max()))
            Q[s][a] += alpha * (target - Q[s][a]); s, a = s2, a2
        totals.append(tot)
    return Q, np.array(totals)
def greedy_path(Q):
    s, path = START, [START]
    for _ in range(60):
        s, _ = step(s, int(np.argmax(Q[s]))); path.append(s)
        if s == GOAL: break
    return path
for kind in ("sarsa", "q"):
    sums = np.mean([learn(kind)[1][-100:].mean() for _ in range(10)])
    Q, _ = learn(kind)
    rows = sorted({p[0] for p in greedy_path(Q)[1:-1]})
    print(f"{kind:>6}: average online return over last 100 episodes = {sums:7.1f}; greedy path uses rows {rows} (row 2 = cliff edge)")

# Maximisation bias: from A, 'right' ends (0); 'left' goes to B, whose 10 actions each give N(-0.1, 1) then end.
def maxbias(double, episodes=300, alpha=0.1, eps=0.1):
    QA = [np.zeros(2), np.zeros(2)]; QB = [np.zeros(10), np.zeros(10)]; left = []
    for _ in range(episodes):
        qa = QA[0] + QA[1] if double else QA[0]
        a = int(rng.integers(2)) if rng.random() < eps else int(np.argmax(qa + rng.random(2) * 1e-9))
        left.append(a == 0)
        if a == 1: 
            i = int(rng.integers(2)) if double else 0; QA[i][1] += alpha * (0 - QA[i][1]); continue
        qb = QB[0] + QB[1] if double else QB[0]
        b = int(rng.integers(10)) if rng.random() < eps else int(np.argmax(qb + rng.random(10) * 1e-9))
        r = rng.normal(-0.1, 1)
        if double:
            i = int(rng.integers(2)); j = 1 - i
            QA[i][0] += alpha * (QB[j][int(np.argmax(QB[i]))] - QA[i][0])
            QB[i][b] += alpha * (r - QB[i][b])
        else:
            QA[0][0] += alpha * (QB[0].max() - QA[0][0]); QB[0][b] += alpha * (r - QB[0][b])
    return np.array(left)
for d in (False, True):
    frac = np.mean([maxbias(d) for _ in range(300)], axis=0)
    print(f"{'Double Q' if d else 'Q-learning':>10}: % 'left' (the worse action) at episodes 10/50/300 = "
          f"{100*frac[9]:.0f}% / {100*frac[49]:.0f}% / {100*frac[-1]:.0f}%   (optimal with eps=0.1: 5%)")
